using namespace std;

int bfs_0(const vector<vector<int>>& adj, int src) { vector<int> dist(adj.size(), -1); queue<int> q; dist[src] = 0; q.push(src); while (!q.empty()) { int u = q.front(); q.pop(); for (int v : adj[u]) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.push(v); } } return dist[adj.size()-1]; }
vector<int> topoSort_0(const vector<vector<int>>& adj, int n) { vector<int> inDeg(n, 0); for (int u = 0; u < n; ++u) for (int v : adj[u]) ++inDeg[v]; queue<int> q; for (int i = 0; i < n; ++i) if (inDeg[i] == 0) q.push(i); vector<int> order; while (!q.empty()) { int u = q.front(); q.pop(); order.push_back(u); for (int v : adj[u]) if (--inDeg[v] == 0) q.push(v); } return order; }
